<template>
    <DebugDisplay :debug="debug"></DebugDisplay>

    <MenuButton @click="add_multiple_button_click()" :disabled="!enable" :disabledReason="disabledReason" iconName="BetweenVerticalStart">
        {{ mstrings['addmultiple'] }}
    </MenuButton>

    <VueModal v-model="showaddmultiplemodal" :enableClose="false" modalClass="rounded max-w-3xl" :title="mstrings['addmultiple']">
        <FormKit type="form" @submit="submit_form">
            <FormKit
                type="select"
                :label="mstrings['reasonforadditionalgrades']"
                name="reason"
                v-model="reason"
                :options="gradetypes"
                :placeholder="mstrings['selectareason']"
                validation="required"
            />
            <FormKit
                v-if = 'reason == "OTHER"'
                :label="mstrings['pleasespecify']"
                type="text"
                :placeholder="mstrings['pleasespecify']"
                name="other"
                v-model="other"
                validation="required"
                :validation-messages="{
                    required: 'This field is required.',
                }"
            />
            <FormKit
                type="textarea"
                label="Notes"
                :placeholder="mstrings['reasonforammendment']"
                name="notes"
                v-model="notes"
            />
        </FormKit>

        <div class="flex justify-end mt-8">
            <UButton variant="warning" @click="showaddmultiplemodal = false">{{ mstrings.cancel }}</UButton>
        </div>
    </VueModal>
</template>

<script setup lang="ts">
    import {ref} from 'vue';
    import { storeToRefs } from 'pinia';
    import { useToast } from "vue-toastification";
    import DebugDisplay from '@/components/Common/DebugDisplay.vue';
    import UButton from '../Common/UButton.vue';
    import MenuButton from '../Common/MenuButton.vue';
    import { useMstrings } from '@/stores/mstrings.js';
    import { moodleFetch } from '@/js/moodlefetch';
    import type { IEmitEditColumn } from '@/js/Interfaces';

    interface GradeType {
        label: string;
        value: string;
    }

    const showaddmultiplemodal = ref(false);
    const gradetypes = ref<GradeType[]>([]);
    const reason = ref('');
    const notes = ref('');
    const other = ref('');
    const debug = ref({});
    const mstringstore = useMstrings();
    const { mstrings } = storeToRefs( mstringstore );

    const emits = defineEmits(['openmultiple']);

    const toast = useToast();

    const props = defineProps({
        enable: {
            type: Boolean,
            default: true,
        },
        disabledReason: {
            type: String,
            default: '',
        },
        itemid: Number,
    });

    /**
     * Button clicked
     */
    function add_multiple_button_click() {

        // Clear for new form
        other.value = '';
        reason.value = '';

        moodleFetch(
            'local_gugrades_get_gradetypes',
            {
                gradeitemid: props.itemid,
            }
        )
        .then((result: any) => {
            gradetypes.value = result.gradetypes;
        })
        .catch((error) => {
            window.console.error(error);
            showaddmultiplemodal.value = false;
            debug.value = error;
        });

        showaddmultiplemodal.value = true;
    }

    /**
     * Process form submission
     */
    function submit_form() {

        // Where reason looks like OTHER_nn,
        // It's an exiting other, the corresponding
        // label is 'other' and reason is 'OTHER'
        if (reason.value.startsWith('OTHER_')) {
            const gtype = gradetypes.value.find(o => o.value == reason.value);
            if (gtype) {
                reason.value = 'OTHER';
                other.value = gtype.label;
            }
        }

        moodleFetch(
            'local_gugrades_write_column',
            {
                gradeitemid: props.itemid,
                reason: reason.value,
                other: other.value,
                notes: notes.value,
            }
        )
        .then((result: any) => {
            const columnid = result.columnid;
            emits('openmultiple', columnid);
        })
        .catch((error) => {
            window.console.error(error);
            showaddmultiplemodal.value = false;
            debug.value = error;
        });

        // close the modal
        showaddmultiplemodal.value = false;
    }
</script>